/* Static chunk transport: no fetch, server or installed runtime is needed for file://. */
(function(g){
'use strict';
const cache=new Map(),pending=new Map();let catalogValue=null,catalogPending=null,packedPending=null,fallbackPending=null,fallbackValue=null;const stats={loads:0,cacheHits:0,peakCachedChunks:0};
function script(url){return new Promise((ok,no)=>{const el=document.createElement('script');el.src=url;el.async=true;el.onload=()=>{el.remove();ok();};el.onerror=()=>{el.remove();no(Error('无法读取资料文件，请检查网络或保留完整本地文件夹：'+url));};document.head.appendChild(el);});}
function remember(url,rows){cache.delete(url);cache.set(url,rows);while(cache.size>2)cache.delete(cache.keys().next().value);stats.peakCachedChunks=Math.max(stats.peakCachedChunks,cache.size);}
async function load(url){if(!/^data\/[a-z]+-\d{3}\.js$/.test(url))throw Error('资料路径不正确。');if(cache.has(url)){stats.cacheHits++;const v=cache.get(url);remember(url,v);return v;}if(pending.has(url))return pending.get(url).promise;
let resolve,reject;const promise=new Promise((a,b)=>{resolve=a;reject=b;});pending.set(url,{resolve,reject,promise});stats.loads++;
script(url).then(()=>{if(pending.has(url)){pending.delete(url);reject(Error('资料文件未能正确注册，请重新解压完整资料包。'));}}).catch(e=>{pending.delete(url);reject(e);});return promise;}
g.ClinicalChunks={load,stats,cacheSize:()=>cache.size,clear:()=>cache.clear(),register(url,rows){if(!pending.has(url))return;const p=pending.get(url);pending.delete(url);if(!Array.isArray(rows)){p.reject(Error('资料分块格式不正确。'));return;}remember(url,rows);p.resolve(rows);},catalog(value){catalogValue=value;},catalogFallback(manifest,parts){fallbackValue={manifest,headers:[]};fallbackPending=(async()=>{for(let i=0;i<parts;i++)await script('data/catalog-part-'+String(i).padStart(3,'0')+'.js');catalogValue=fallbackValue;fallbackValue=null;})();},catalogPart(index,headers){if(!fallbackValue)throw Error('目录加载顺序不正确。');fallbackValue.headers.push(...headers);},catalogPacked(base64){packedPending=(async()=>{if(typeof DecompressionStream==='undefined'){await script('data/catalog-fallback.js');if(fallbackPending)await fallbackPending;return;}const binary=atob(base64),bytes=new Uint8Array(binary.length);for(let i=0;i<binary.length;i++)bytes[i]=binary.charCodeAt(i);const stream=new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'));catalogValue=await new Response(stream).json();})();},async getCatalog(){if(catalogValue)return catalogValue;if(!catalogPending)catalogPending=script('data/catalog.js').then(async()=>{if(packedPending)await packedPending;if(!catalogValue)throw Error('资料目录无法读取。');return catalogValue;});return catalogPending;}};
})(window);
